require __DIR__.'/app/bootstrap.php';$ctx=growth_seller_context('orders');$u=$ctx['user'];$uid=(int)$ctx['owner_id'];$msg=$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$id=(int)$_POST['id'];$q=db()->prepare('SELECT * FROM store_orders WHERE id=? AND seller_user_id=?');$q->execute([$id,$uid]);$o=$q->fetch();if(!$o)throw new RuntimeException('Order not found.');$st=in_array($_POST['status']??'confirmed',['confirmed','processing','shipped','delivered','completed','cancelled'],true)?$_POST['status']:'confirmed';if(function_exists('operations_set_order_status'))operations_set_order_status($id,$st,(int)$u['id'],$uid);elseif($st==='cancelled')store_cancel_order($id);else db()->prepare('UPDATE store_orders SET status=? WHERE id=? AND seller_user_id=?')->execute([$st,$id,$uid]);$msg='Order status updated.';}catch(Throwable $e){$err=$e->getMessage();}}$q=db()->prepare('SELECT o.*,u.name buyer_name FROM store_orders o JOIN users u ON u.id=o.buyer_user_id WHERE o.seller_user_id=? ORDER BY o.id DESC');$q->execute([$uid]);$orders=$q->fetchAll();$stats=store_seller_stats($uid);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seller Orders</title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"><link rel="stylesheet" href="/assets/live-commerce-admin-3.4.0.css?v=340"></head><body class="lc-page"><header class="lc-public-header"><div class="lt-shell"><a class="lc-public-brand" href="/seller.php">Seller Center</a><nav class="lc-public-nav"><a href="/shopkeeper-products.php">Products</a><a href="/shopkeeper-orders.php">Orders</a><a href="/shopkeeper-auctions.php">Auctions</a></nav></div></header><section class="shop-section"><div class="lt-shell"><div class="lca-kpis"><article><b><?=e($stats['orders']??0)?></b><span>Orders</span></article><article><b><?=e($stats['open_orders']??0)?></b><span>Open Orders</span></article><article><b>Rs <?=e(number_format((float)($stats['gross']??0),0))?></b><span>Gross Value</span></article><article><b><?=e($stats['published']??0)?></b><span>Live Products</span></article></div><?php if($msg):?><div class="lc-empty" style="color:#166534"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="lc-empty" style="color:#991b1b"><?=e($err)?></div><?php endif;?><div class="shop-panel"><table class="cart-table"><tr><th>Order</th><th>Buyer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td><a target="_blank" href="/order.php?id=<?=e($o['id'])?>"><?=e($o['order_number'])?></a></td><td><?=e($o['buyer_name'])?><br><small><?=e($o['customer_phone'])?></small></td><td>Rs <?=e(number_format((float)$o['grand_total'],0))?></td><td><?=e($o['payment_method'].' / '.$o['payment_status'])?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($o['id'])?>"><select name="status" onchange="this.form.submit()"><option><?=e($o['status'])?></option><option value="confirmed">Confirmed</option><option value="processing">Processing</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></form></td></tr><?php endforeach;?></table></div></div></section></body></html>
